    static uint8_t _illegal_fp_reduction_widen(void* vm_impl_ptr , uint8_t SEW, uint8_t rm, uint8_t EEW){
         return reinterpret_cast<this_class*>(vm_impl_ptr)->illegal_fp_reduction_widen(SEW,rm,EEW);
    }
    uint8_t illegal_fp_reduction_widen(uint8_t SEW, uint8_t rm, uint8_t EEW){
        return illegal_fp_reduction(SEW, rm) || ! (EEW >= 8 && EEW <= traits::ELEN);
    }
